using System.Reflection;
using TownOfHost;
using UnityEngine;
partial class Program {
 static void RequestSettingsClose(OptionsMenuBehaviour ui){var p=typeof(SeasideMainMenuPatch).GetMethod("OptionsClosing",BindingFlags.Static|BindingFlags.NonPublic);bool native=p==null||(bool)p.Invoke(null,new object[]{ui});if(native)ui.Close();Call("CloseOptions",ui);}
 static void ReproduceOptionsCloseSlide(){var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu);RequestSettingsClose(x.ui);Check(x.ui.IsOpen&&x.ui.gameObject.activeSelf&&x.view.OptionsBlocking);PumpSettings(x.menu,20);Check(!x.ui.IsOpen&&x.ui.CloseCalls==1&&x.view.Visible&&!x.view.OptionsBlocking);x.view.Dispose();}

 static void DrainSettingsClose(MainMenuManager menu,OptionsMenuBehaviour ui){for(int i=0;i<40&&ui.IsOpen;i++)PumpSettings(menu,1);}
 static void OptionsCloseSlideTests(){
  Test("settings close slides off-screen before native Close runs once",ReproduceOptionsCloseSlide);
  Test("closing requests leave native modal alive for the animation",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);Check(x.ui.IsOpen&&x.ui.CloseCalls==0&&SeasideMainMenuPatch.DefersOptionsClose(x.ui)&&x.view.OptionsBlocking);DrainSettingsClose(x.menu,x.ui);Check(x.ui.CloseCalls==1&&!x.ui.IsOpen&&OptionsPanel==null);x.view.Dispose();});
  Test("closing moves monotonically down from the visible position",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);var start=x.ui.transform.localPosition;RequestSettingsClose(x.ui);Near(x.ui.transform.localPosition.y,start.y);float previous=start.y;for(int i=0;i<30&&x.ui.IsOpen;i++){PumpSettings(x.menu,1);if(x.ui.IsOpen){Check(x.ui.transform.localPosition.y<=previous);previous=x.ui.transform.localPosition.y;}}Check(previous<start.y-1&&!x.ui.IsOpen);Near(x.ui.transform.localPosition.y,.3);x.view.Dispose();});
  Test("closing duration matches 0.32 seconds within one update",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);PumpSettings(x.menu,15);Check(x.ui.IsOpen&&x.ui.CloseCalls==0);PumpSettings(x.menu,2);Check(!x.ui.IsOpen&&x.ui.CloseCalls==1);x.view.Dispose();});
  Test("close during opening reverses without snapping to the resting pose",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,6);var y=x.ui.transform.localPosition.y;RequestSettingsClose(x.ui);Near(x.ui.transform.localPosition.y,y);PumpSettings(x.menu,1);Check(x.ui.transform.localPosition.y<y&&x.ui.IsOpen);DrainSettingsClose(x.menu,x.ui);Check(x.ui.CloseCalls==1);x.view.Dispose();});
  Test("repeated close and ESC requests do not reset time or double-pop",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);PumpSettings(x.menu,5);var y=x.ui.transform.localPosition.y;for(int i=0;i<30;i++)RequestSettingsClose(x.ui);Near(x.ui.transform.localPosition.y,y);PumpSettings(x.menu,12);Check(x.ui.CloseCalls==1&&!x.ui.IsOpen);x.view.Dispose();});
  Test("settings native input is blocked during slide-out and restored afterwards",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);Check(!x.row.Colliders[0].enabled&&!(bool)Call("StartupClick",x.row)&&!(bool)Call("StartupClick",Proxy("Play")));DrainSettingsClose(x.menu,x.ui);Check(x.row.Colliders[0].enabled&&Proxy("Play").Colliders[0].enabled);x.view.Dispose();});
  Test("pre-disabled native collider remains disabled after close",()=>{var x=SettingsSlideFixture();x.row.Colliders[0].enabled=false;OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);DrainSettingsClose(x.menu,x.ui);Check(!x.row.Colliders[0].enabled);x.view.Dispose();});
  Test("late-created modal controls are blocked and restored on closing",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);var c=new GameObject("LateNativeControl").AddComponent<BoxCollider2D>();c.transform.SetParent(x.ui.transform,false);PumpSettings(x.menu,1);Check(!c.enabled);DrainSettingsClose(x.menu,x.ui);Check(c.enabled);x.view.Dispose();});
  Test("slide-out preserves dimensions scale rotation and X coordinate",()=>{var x=SettingsSlideFixture();x.ui.transform.localRotation=Quaternion.Euler(0,0,2);OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);var pos=x.ui.transform.localPosition;var scale=x.ui.transform.localScale;RequestSettingsClose(x.ui);for(int i=0;i<10;i++){PumpSettings(x.menu,1);Near(x.ui.transform.localPosition.x,pos.x);Near(x.ui.transform.localPosition.z,pos.z);Near(x.ui.transform.localScale.x,scale.x);Near(x.ui.transform.localScale.y,scale.y);Near(x.ui.transform.localRotation.Z,2);}DrainSettingsClose(x.menu,x.ui);x.view.Dispose();});
  Test("settled native anchor changes define the current slide-out position",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);x.ui.transform.localPosition=new(.8f,.75f,-15);RequestSettingsClose(x.ui);Near(x.ui.transform.localPosition.y,.75);PumpSettings(x.menu,1);Check(x.ui.transform.localPosition.y<.75);DrainSettingsClose(x.menu,x.ui);Near(x.ui.transform.localPosition.y,.75);Near(x.ui.transform.localPosition.x,.8);x.view.Dispose();});
  Test("open during slide-out reverses in place without native overlay duplication",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);var nav=ControllerManager.Instance.CurrentUiState;RequestSettingsClose(x.ui);PumpSettings(x.menu,5);var y=x.ui.transform.localPosition.y;Check(!(bool)Call("OpenOptions",x.ui));Call("OptionsOpened",x.ui);Near(x.ui.transform.localPosition.y,y);Check(x.row.Colliders[0].enabled&&!SeasideMainMenuPatch.DefersOptionsClose(x.ui));PumpSettings(x.menu,20);Near(x.ui.transform.localPosition.y,.3);Check(x.ui.CloseCalls==0&&ControllerManager.Instance.CurrentUiState==nav);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("fully open native Open toggle remains available for the vanilla ESC route",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);Check((bool)Call("OpenOptions",x.ui));RequestSettingsClose(x.ui);Check(SeasideMainMenuPatch.DefersOptionsClose(x.ui));DrainSettingsClose(x.menu,x.ui);Check(x.ui.CloseCalls==1&&!x.ui.IsOpen);x.view.Dispose();});
  Test("forced disable cancels closing and restores transforms and native inputs",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);PumpSettings(x.menu,3);x.ui.IsOpen=false;x.ui.gameObject.SetActive(false);Call("OptionsDisabled",x.ui);Check(OptionsPanel==null&&!x.view.OptionsBlocking&&x.row.Colliders[0].enabled);Near(x.ui.transform.localPosition.y,.3);PumpSettings(x.menu,20);Check(x.ui.CloseCalls==0);x.view.Dispose();});
  Test("destroying settings during slide-out releases all ownership",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);Call("OptionsDestroyed",x.ui);Check(OptionsPanel==null&&!x.view.OptionsBlocking&&x.row.Colliders[0].enabled);x.view.Dispose();});
  Test("scene departure cancels the presentation without closing a foreign game UI",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);GameScene();Call("BeforeCamera",Camera.main);Check(OptionsPanel==null&&Home==null&&x.ui.CloseCalls==0&&x.row.Colliders[0].enabled);});
  Test("foreign and gameplay settings keep immediate native close",()=>{var x=SettingsSlideFixture();var other=Settings();other.IsOpen=true;RequestSettingsClose(other);Check(!other.IsOpen&&other.CloseCalls==1&&x.view.Visible);GameScene();var game=Settings();game.IsOpen=true;RequestSettingsClose(game);Check(!game.IsOpen&&game.CloseCalls==1);});
  Test("invalid camera before close falls back to native close immediately",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);Camera.main.orthographic=false;RequestSettingsClose(x.ui);Check(!x.ui.IsOpen&&x.ui.CloseCalls==1&&OptionsPanel==null);Camera.main.orthographic=true;x.view.Dispose();});
  Test("lost camera mid-close completes native cleanup once",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);PumpSettings(x.menu,2);var camera=Camera.main;Camera.main=null;Call("TickOptions");Check(!x.ui.IsOpen&&x.ui.CloseCalls==1&&OptionsPanel==null&&x.row.Colliders[0].enabled);Camera.main=camera;x.view.Dispose();});
  Test("native close failure leaves a readable interactive modal with safe retry",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);x.ui.CloseFailure=new Exception("synthetic native close failure");RequestSettingsClose(x.ui);PumpSettings(x.menu,40);Check(x.ui.IsOpen&&x.row.Colliders[0].enabled&&OptionsPanel!=null&&x.view.OptionsBlocking&&x.row.GetComponent<SpriteRenderer>().sortingOrder==27);Near(x.ui.transform.localPosition.y,.3);x.ui.CloseFailure=null;RequestSettingsClose(x.ui);DrainSettingsClose(x.menu,x.ui);Check(!x.ui.IsOpen&&!x.view.OptionsBlocking&&x.ui.CloseCalls==2);x.view.Dispose();});
  Test("custom options cleanup is deferred until native close actually runs",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);int cleanups=0;var custom=new GameObject("CustomOptionsPage");x.ui.CloseAction=()=>{if(!SeasideMainMenuPatch.DefersOptionsClose(x.ui)){custom.SetActive(false);cleanups++;}Call("OptionsDisabled",x.ui);Call("CloseOptions",x.ui);};RequestSettingsClose(x.ui);if(!SeasideMainMenuPatch.DefersOptionsClose(x.ui)){custom.SetActive(false);cleanups++;}Check(custom.activeSelf&&cleanups==0);DrainSettingsClose(x.menu,x.ui);Check(!custom.activeSelf&&cleanups==1&&x.ui.CloseCalls==1);x.view.Dispose();});
  Test("source cleanup guard precedes custom page teardown even on skipped Harmony originals",()=>{var file=Path.Combine(Path.GetDirectoryName(GetCloseTestPath()),"../../Patches/ClientOptionsPatch.cs");var src=File.ReadAllText(file);int start=src.IndexOf("public static class OptionsMenuBehaviourClosePatch");var body=src.Substring(start);Check(body.IndexOf("DefersOptionsClose(__instance)")>=0&&body.IndexOf("DefersOptionsClose(__instance)")<body.IndexOf("ClientActionItem.CustomBackground.gameObject.SetActive(false)"));});
  Test("release frame cannot click through into an underlying home proxy",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);DrainSettingsClose(x.menu,x.ui);Check(!(bool)Call("StartupClick",Proxy("Play")));PumpSettings(x.menu,1);Check((bool)Call("StartupClick",Proxy("Play")));x.view.Dispose();});
  Test("ten animated open-close cycles leave no position drift or extra native closes",()=>{var x=SettingsSlideFixture();for(int i=0;i<10;i++){OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);DrainSettingsClose(x.menu,x.ui);Near(x.ui.transform.localPosition.y,.3);Check(x.view.Visible&&!x.view.OptionsBlocking&&x.row.Colliders[0].enabled&&x.ui.CloseCalls==i+1);PumpSettings(x.menu,6);}x.view.Dispose();});
  Test("duplicate native completion callbacks cannot run Close a second time",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);var panel=OptionsPanel;DrainSettingsClose(x.menu,x.ui);Call("CompleteOptionsClose",panel);Check(x.ui.CloseCalls==1);x.view.Dispose();});
  Test("native reset during slide-out keeps sunset backdrop and the close timeline",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);PumpSettings(x.menu,20);RequestSettingsClose(x.ui);PumpSettings(x.menu,4);Call("Reset",x.menu);Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&SeasideMainMenuPatch.DefersOptionsClose(x.ui));DrainSettingsClose(x.menu,x.ui);Check(x.view.Visible&&x.ui.CloseCalls==1);x.view.Dispose();});
 }
 static string GetCloseTestPath([System.Runtime.CompilerServices.CallerFilePath]string file="")=>file;
}
